package dev.kyrion.core.security

import java.util.UUID
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Test

class OperationalTransferPermitTest {
    private val key = ByteArray(32) { 'A'.code.toByte() }
    // Generated by the Python installer authority module with a synthetic key.
    private val receipt = """{"transfer":{"formatVersion":1,"kind":"kyrion-authority-transfer","sourceInstallationId":"11111111-1111-4111-8111-111111111111","targetInstallationId":"22222222-2222-4222-8222-222222222222","backupSha256":"${"a".repeat(64)}"},"authentication":"550ef1b084b0dc69a94caf717d42b0719e8e58d5375fa5d0412089218dc17144"}"""

    @Test
    fun `Python transfer receipt is authenticated without copying a web password`() {
        val permit = OperationalTransferPermit.verify(receipt.toByteArray(), key)
        assertEquals(UUID.fromString("22222222-2222-4222-8222-222222222222"), permit.target)
        assertEquals("a".repeat(64), permit.backupSha256)
    }

    @Test
    fun `changed target or signing key cannot authorize restoration`() {
        assertThrows(Exception::class.java) {
            OperationalTransferPermit.verify(receipt.replace("22222222-2222-4222-8222-222222222222", "33333333-3333-4333-8333-333333333333").toByteArray(), key)
        }
        assertThrows(Exception::class.java) { OperationalTransferPermit.verify(receipt.toByteArray(), ByteArray(32)) }
    }

    @Test
    fun `ambiguous numeric types duplicates and oversize receipts fail closed`() {
        for (invalid in listOf(
            receipt.replace("\"formatVersion\":1", "\"formatVersion\":true"),
            receipt.replace("\"formatVersion\":1", "\"formatVersion\":1.0"),
            receipt.replace("\"formatVersion\":1", "\"formatVersion\":1,\"formatVersion\":1"),
            "x".repeat(4097), "[]", "",
        )) {
            assertThrows(Exception::class.java) { OperationalTransferPermit.verify(invalid.toByteArray(), key) }
        }
    }
}
